use split_decls_genesis :: ourprelude :: * ; use crate :: future :: Future ; #[doc = " Conversion into a `Future`."] #[doc = ""] #[doc = " By implementing `IntoFuture` for a type, you define how it will be"] #[doc = " converted to a future."] #[doc = ""] #[doc = " # `.await` desugaring"] #[doc = ""] #[doc = " The `.await` keyword desugars into a call to `IntoFuture::into_future`"] #[doc = " first before polling the future to completion. `IntoFuture` is implemented"] #[doc = " for all `T: Future` which means the `into_future` method will be available"] #[doc = " on all futures."] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::future::IntoFuture;"] #[doc = ""] #[doc = " # async fn foo() {"] #[doc = " let v = async { \"meow\" };"] #[doc = " let mut fut = v.into_future();"] #[doc = " assert_eq!(\"meow\", fut.await);"] #[doc = " # }"] #[doc = " ```"] #[doc = ""] #[doc = " # Async builders"] #[doc = ""] #[doc = " When implementing futures manually there will often be a choice between"] #[doc = " implementing `Future` or `IntoFuture` for a type. Implementing `Future` is a"] #[doc = " good choice in most cases. But implementing `IntoFuture` is most useful when"] #[doc = " implementing \"async builder\" types, which allow their values to be modified"] #[doc = " multiple times before being `.await`ed."] #[doc = ""] #[doc = " ```rust"] #[doc = " use std::future::{ready, Ready, IntoFuture};"] #[doc = ""] #[doc = " /// Eventually multiply two numbers"] #[doc = " pub struct Multiply {"] #[doc = "     num: u16,"] #[doc = "     factor: u16,"] #[doc = " }"] #[doc = ""] #[doc = " impl Multiply {"] #[doc = "     /// Constructs a new instance of `Multiply`."] #[doc = "     pub fn new(num: u16, factor: u16) -> Self {"] #[doc = "         Self { num, factor }"] #[doc = "     }"] #[doc = ""] #[doc = "     /// Set the number to multiply by the factor."] #[doc = "     pub fn number(mut self, num: u16) -> Self {"] #[doc = "         self.num = num;"] #[doc = "         self"] #[doc = "     }"] #[doc = ""] #[doc = "     /// Set the factor to multiply the number with."] #[doc = "     pub fn factor(mut self, factor: u16) -> Self {"] #[doc = "         self.factor = factor;"] #[doc = "         self"] #[doc = "     }"] #[doc = " }"] #[doc = ""] #[doc = " impl IntoFuture for Multiply {"] #[doc = "     type Output = u16;"] #[doc = "     type IntoFuture = Ready<Self::Output>;"] #[doc = ""] #[doc = "     fn into_future(self) -> Self::IntoFuture {"] #[doc = "         ready(self.num * self.factor)"] #[doc = "     }"] #[doc = " }"] #[doc = ""] #[doc = " // NOTE: Rust does not yet have an `async fn main` function, that functionality"] #[doc = " // currently only exists in the ecosystem."] #[doc = " async fn run() {"] #[doc = "     let num = Multiply::new(0, 0)  // initialize the builder to number: 0, factor: 0"] #[doc = "         .number(2)                 // change the number to 2"] #[doc = "         .factor(2)                 // change the factor to 2"] #[doc = "         .await;                    // convert to future and .await"] #[doc = ""] #[doc = "     assert_eq!(num, 4);"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " # Usage in trait bounds"] #[doc = ""] #[doc = " Using `IntoFuture` in trait bounds allows a function to be generic over both"] #[doc = " `Future` and `IntoFuture`. This is convenient for users of the function, so"] #[doc = " when they are using it they don't have to make an extra call to"] #[doc = " `IntoFuture::into_future` to obtain an instance of `Future`:"] #[doc = ""] #[doc = " ```rust"] #[doc = " use std::future::IntoFuture;"] #[doc = ""] #[doc = " /// Converts the output of a future to a string."] #[doc = " async fn fut_to_string<Fut>(fut: Fut) -> String"] #[doc = " where"] #[doc = "     Fut: IntoFuture,"] #[doc = "     Fut::Output: std::fmt::Debug,"] #[doc = " {"] #[doc = "     format!(\"{:?}\", fut.await)"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "into_future" , since = "1.64.0")] #[rustc_diagnostic_item = "IntoFuture"] #[diagnostic :: on_unimplemented (label = "`{Self}` is not a future" , message = "`{Self}` is not a future" , note = "{Self} must be a future or must implement `IntoFuture` to be awaited")] pub trait IntoFuture { #[doc = " The output that the future will produce on completion."] #[stable (feature = "into_future" , since = "1.64.0")] type Output ; #[doc = " Which kind of future are we turning this into?"] #[stable (feature = "into_future" , since = "1.64.0")] type IntoFuture : Future < Output = Self :: Output > ; #[doc = " Creates a future from a value."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " Basic usage:"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::future::IntoFuture;"] #[doc = ""] #[doc = " # async fn foo() {"] #[doc = " let v = async { \"meow\" };"] #[doc = " let mut fut = v.into_future();"] #[doc = " assert_eq!(\"meow\", fut.await);"] #[doc = " # }"] #[doc = " ```"] #[stable (feature = "into_future" , since = "1.64.0")] #[lang = "into_future"] fn into_future (self) -> Self :: IntoFuture ; } #[stable (feature = "into_future" , since = "1.64.0")] impl < F : Future > IntoFuture for F { type Output = F :: Output ; type IntoFuture = F ; fn into_future (self) -> Self :: IntoFuture { self } }